import {validateMessage} from './validation.js';

// Spec: specs/hal-engine-conversation-list/spec.md — Over the WebSocket protocol, validator contract.
describe('list_sessions validation', () => {
  it('validates paging fields and strips fields outside the list_sessions frame', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
    for (const updatedAt of ['2026-10-06T09:30:22.517Z', 0]) {
      const before = {sessionId: 's'.repeat(128), updatedAt};
      expect(validateMessage({type: 'list_sessions', limit: 0, before, userId: 'other'})).toEqual({
        valid: true,
        data: {type: 'list_sessions', limit: 0, before},
      });
    }
    for (const limit of [-1, 1.5, '10', NaN, Infinity]) {
      expect(validateMessage({type: 'list_sessions', limit})).toEqual({
        valid: false,
        error: expect.stringContaining('limit'),
      });
    }
    for (const before of [null, [], {}, {sessionId: '', updatedAt: 0}, {sessionId: 's'.repeat(129), updatedAt: 0}, {sessionId: 's', updatedAt: 'not a date'}, {sessionId: 's', updatedAt: Infinity}, {sessionId: 's', updatedAt: true}]) {
      expect(validateMessage({type: 'list_sessions', before})).toEqual({
        valid: false,
        error: expect.stringContaining('before'),
      });
    }
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsValidation.test.ts --runInBand"

